type Go = (path: string) => void;
function message(error: unknown): string {
  if (error instanceof ApiError && error.status === 403) return 'Your current role or workspace activation does not allow this action. Ask your workspace administrator to review access.';
  if (error instanceof ApiError && error.status === 412) return 'This record changed while you were reviewing it. Refresh the record and review the latest version before trying again.';
  return error instanceof Error ? error.message : 'This information is temporarily unavailable. Try again.';
}
function date(value: string | null | undefined): string { if (!value) return 'Not reported'; const parsed = new Date(value); return Number.isNaN(parsed.getTime()) ? 'Time unavailable' : parsed.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }); }
function useRemote<T>(api: PackProofApi, path: string | null, revision = 0) {
  const [state, setState] = useState<{ api: PackProofApi; path: string; data: T | null; error: string | null; loading: boolean } | null>(null);
  useEffect(() => { if (!path) return; let active = true; setState(previous => ({ api, path, data: previous?.api === api && previous.path === path ? previous.data : null, error: null, loading: true }));
    void api.recordsRequest<T>(path).then(data => { if (active) setState({ api, path, data, error: null, loading: false }); }).catch(error => { if (active) setState({ api, path, data: null, error: message(error), loading: false }); });
    return () => { active = false; };
  }, [api, path, revision]);
  return !path ? { data: null, error: null, loading: false } : state?.api === api && state.path === path ? state : { data: null, error: null, loading: true };
}
function Status({ value, children }: { value: unknown; children?: ReactNode }) { const tone = stateTone(value); return <span className={`records-status ${tone}`}><Glyph size={13} name={tone === 'success' ? 'check' : tone === 'error' || tone === 'warning' ? 'alert' : 'info'}/>{children ?? displayState(value)}</span>; }
function Loading({ children = 'Loading records…' }: { children?: ReactNode }) { return <div className="records-loading" role="status"><Glyph name="clock"/><span>{children}</span></div>; }
function Empty({ title, children, action }: { title: string; children: ReactNode; action?: ReactNode }) { return <div className="records-empty"><span className="records-empty-icon"><Glyph name="file" size={28}/></span><h2>{title}</h2><p>{children}</p>{action}</div>; }
function Failure({ error, onRetry }: { error: string; onRetry: () => void }) { return <div className="records-notice error" role="alert"><Glyph name="alert"/><div><strong>Information unavailable</strong><p>{error}</p><button className="records-button secondary" onClick={onRetry}>Try again</button></div></div>; }
function LocalLink({ href, onGo, children, ...props }: { href: string; onGo: Go; children: ReactNode; className?: string; 'aria-current'?: 'page'; title?: string; id?: string; 'data-context-anchor'?: string }) { return <a {...props} href={href} onClick={event => { if (!event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey) { event.preventDefault(); onGo(href); } }}>{children}</a>; }
function scopeQuery(organization: RecordOrganization, locationId: string | null) { const params = new URLSearchParams({ organizationId: organization.id, environment: organization.environment }); if (locationId) params.set('locationId', locationId); return params; }
function RecordReference({ record }: { record: RecordSummary }) { return <><strong>{record.reference || record.id}</strong><small>{record.title || 'Shipping evidence record'}</small></>; }

function RecordsListScreen({ api, organization, params, revision, onGo, onRefresh }: { api: PackProofApi; organization: RecordOrganization; params: URLSearchParams; revision: number; onGo: Go; onRefresh: () => void }) {
  const [search, setSearch] = useState(params.get('q') || ''), [updates, setUpdates] = useState(false), searchRef = useRef<HTMLInputElement>(null);
  const q = params.get('q') || '', view = params.get('view') || 'all', locationId = params.get('locationId');
  const query = scopeQuery(organization, locationId);
  for (const key of ['q', 'view', 'cursor', 'from', 'to']) { const value = params.get(key); if (value) query.set(key, value); }
  const result = useRemote<RecordsList>(api, `?${query}`, revision);
  const connectionScope = scopeQuery(organization, locationId).toString();
  const connectionHealth = useRemote<{ currentNeedsAction?: number }>(api, `/connections?${connectionScope}`, revision);
  useEffect(() => setSearch(q), [q]);
  useEffect(() => { const changed = () => setUpdates(true); const shortcut = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); searchRef.current?.focus(); } }; window.addEventListener('packproof:records-updated', changed); window.addEventListener('online', changed); window.addEventListener('keydown', shortcut); return () => { window.removeEventListener('packproof:records-updated', changed); window.removeEventListener('online', changed); window.removeEventListener('keydown', shortcut); }; }, []);
  useEffect(() => { if (result.loading) setUpdates(false); }, [result.loading]);
  const navigate = (changes: Record<string, string | null>) => onGo(recordsPath('records', params, { cursor: null, ...changes }));
  const cohort = params.get('from') || params.get('to') ? `${params.get('from') ? date(params.get('from')) : 'Beginning'} – ${params.get('to') ? date(params.get('to')) : 'Now'}` : 'All creation dates';
  const data = result.data;
  return <>
    <header className="records-page-heading"><div><span className="records-eyebrow">YOUR OPERATION, IN ONE RECORD</span><h1>Shipping records</h1><p>Find the shipment. Follow the history. Open the evidence.</p></div><LocalLink className="records-button" href={recordsPath('setup', params, { cursor: null })} onGo={onGo}><Glyph name="plus" size={18}/>Connect or import</LocalLink></header>
    <div className="records-first-run" aria-label="Workspace getting started"><span><Glyph name="check" size={14}/>Workspace selected</span><LocalLink href={recordsPath('setup', params)} onGo={onGo}>Connect or import</LocalLink>{data?.records[0] ? <LocalLink href={recordsPath('records', params, {}, data.records[0].id)} onGo={onGo}>Inspect your first record</LocalLink> : <span>Inspect your first record</span>}<LocalLink href={recordsPath('connections', params)} onGo={onGo}>Review source health</LocalLink></div>
    <div className="records-cohort"><Glyph name="pin" size={15}/><span>{organization.name} · {locationId ? organization.locations.find(location => location.id === locationId)?.name || 'Selected location' : 'All permitted locations'} · {cohort}</span>{organization.environment !== 'live' && <Status value="sandbox">Sandbox — excluded from production totals</Status>}</div>
    <div className="records-metrics" aria-label="Counts for the selected record creation cohort">{[
      { title: 'Records created', value: data?.counts.total, view: 'all', icon: 'file', description: 'In the selected creation period' },
      { title: 'Needs attention', value: data?.counts.needsAttention, view: 'needs_attention', icon: 'alert', description: 'Within the same record cohort' },
      { title: 'Policy complete', value: data?.counts.policyComplete, view: 'ready', icon: 'check', description: 'Required evidence satisfied or waived' },
    ].map(metric => <button key={metric.title} className={`records-metric ${view === metric.view ? 'selected' : ''}`} onClick={() => navigate({ view: metric.view })}><span><Glyph name={metric.icon} size={17}/>{metric.title}</span><strong>{metric.value?.toLocaleString() ?? '—'}</strong><small>{metric.description}</small></button>)}</div>
    <div className="records-current-health"><Glyph name="link" size={16}/><div><strong>Connections needing action: {connectionHealth.data?.currentNeedsAction?.toLocaleString() ?? 'Not measured'}</strong><span>Current source health for permitted locations; independent of record creation dates.{connectionHealth.error ? ' Health information is unavailable for this view.' : ''}</span></div><LocalLink href={recordsPath('connections', params)} onGo={onGo}>Review connections</LocalLink></div>
    <section className="records-panel library-page" aria-label="Shipment records" aria-busy={result.loading}>
      <div className="records-list-controls"><form role="search" className="records-search" onSubmit={event => { event.preventDefault(); navigate({ q: search.trim() || null }); }}><Glyph name="file" size={18}/><label className="visually-hidden" htmlFor="records-search">Search shipment, order, tracking, or record ID</label><input ref={searchRef} id="records-search" value={search} onChange={event => setSearch(event.target.value)} placeholder="Search shipment, order, tracking, or record ID" autoComplete="off"/><button type="submit" className="records-button secondary">Search</button></form><button className="records-button secondary" onClick={onRefresh} disabled={result.loading}>Refresh</button></div>
      <div className="records-saved-views" aria-label="Saved record views">{[['all', 'All records'], ['needs_attention', 'Needs attention'], ['missing', 'Missing evidence'], ['processing', 'Processing problems'], ['ready', 'Ready to export']].map(([key, label]) => <button key={key} aria-pressed={view === key} onClick={() => navigate({ view: key })}>{label}</button>)}<details><summary>More views</summary><div><button onClick={() => navigate({ view: 'open' })}>Open workflows</button><button onClick={() => navigate({ view: 'closed' })}>Closed workflows</button><button onClick={() => navigate({ view: 'handoffs' })}>Missing handoff evidence</button><LocalLink href={recordsPath('connections', params, { cursor: null })} onGo={onGo}>Check source freshness</LocalLink></div></details></div>
      <div className="records-filters"><label>Created from<input type="date" value={(params.get('from') || '').slice(0, 10)} onChange={event => navigate({ from: event.target.value ? `${event.target.value}T00:00:00.000Z` : null })}/></label><label>Created before<input type="date" value={(params.get('to') || '').slice(0, 10)} onChange={event => navigate({ to: event.target.value ? `${event.target.value}T00:00:00.000Z` : null })}/></label><small>Creation dates use UTC. Source-reported times are shown in each record.</small>{(q || view !== 'all' || params.get('from') || params.get('to')) && <button className="records-text-button" onClick={() => navigate({ q: null, view: null, from: null, to: null })}>Clear filters</button>}</div>
      {updates && <div className="records-list-notice" role="status">New information may be available. <button className="records-text-button" onClick={onRefresh}>Refresh when you’re ready</button></div>}
      {result.error ? <Failure error={result.error} onRetry={onRefresh}/> : result.loading && !data ? <Loading/> : data && <>
        {q && <p className="records-list-notice">Results for “{q}”. Exact identifiers are matched before descriptive text.</p>}
        {data.records.length ? <div className="records-table-wrap"><table className="records-table"><caption className="visually-hidden">Records in {organization.name}. Last PackProof update is the latest committed record change.</caption><thead><tr><th scope="col">Shipment reference</th><th scope="col">Source &amp; site</th><th scope="col">Workflow</th><th scope="col">Evidence coverage</th><th scope="col">Attention</th><th scope="col">Last PackProof update</th></tr></thead><tbody>{data.records.map(record => <tr key={record.id}><td><LocalLink className="records-record-link" id={`record-${record.id}`} data-context-anchor={`record-${record.id}`} href={recordsPath('records', params, {}, record.id)} onGo={onGo}><RecordReference record={record}/>{record.sample && <Status value="sample">Sample</Status>}</LocalLink></td><td><span>{record.sourceName || record.source?.name || 'Source not specified'}</span><small>{record.locationId ? organization.locations.find(location => location.id === record.locationId)?.name || record.locationId : 'Location not supplied'}</small></td><td><Status value={record.lifecycle}/><small>{record.carrier || 'Carrier not supplied'}</small></td><td><span className="records-coverage"><strong>{record.coverage.satisfied + record.coverage.waived}/{record.coverage.total}</strong><span>{record.coverage.total ? 'requirements met' : 'No policy assigned'}</span></span><small>{record.coverage.missing ? `${record.coverage.missing} required item${record.coverage.missing === 1 ? '' : 's'} missing` : record.coverage.notYetDue ? `${record.coverage.notYetDue} not yet due` : 'Review requirements in record'}</small></td><td><Status value={record.review}>{record.issueCount ? `${record.issueCount} issue${record.issueCount === 1 ? '' : 's'}` : displayState(record.review)}</Status></td><td><time dateTime={record.updatedAt}>{date(record.updatedAt)}</time><small>Revision {record.revision}</small></td></tr>)}</tbody></table></div> : <Empty title={q || view !== 'all' || params.get('from') || params.get('to') ? 'No records match this view' : 'Ready for your first shipping record'} action={<LocalLink className="records-button" href={recordsPath('setup', params)} onGo={onGo}>Import a shipment spreadsheet</LocalLink>}>{q || view !== 'all' ? 'Try another reference or clear your filters. Your access is checked for every search.' : 'Connect an authorized source or upload a spreadsheet. Your original information and its source will stay together.'}</Empty>}
        <div className="records-pagination"><span>{data.records.length.toLocaleString()} shown · refreshed {date(data.updatedAt)}</span>{params.get('cursor') && <button className="records-button secondary" onClick={() => navigate({})}>First page</button>}{data.nextCursor && <button className="records-button secondary" onClick={() => onGo(recordsPath('records', params, { cursor: data.nextCursor }))}>Next page<Glyph size={16}/></button>}</div>
      </>}
    </section>
    <div className="records-bottom-note"><Glyph name="shield" size={17}/><p>File integrity, evidence coverage, review state, and physical shipping outcomes are separate checks. A passed file check does not establish a shipment’s condition.</p></div>
  </>;
}

function IssueCard({ issue, record, api, query, canReview, canAssign=false, onUpdated }: { issue: RecordIssue; record?: RecordSummary; api: PackProofApi; query: string; canReview: boolean; canAssign?: boolean; onUpdated: () => void }) {
  const [reason, setReason] = useState(''), [action, setAction] = useState('note'), [busy, setBusy] = useState(false), [error, setError] = useState<string | null>(null);
  const commandKey = useRef(randomId());
  useEffect(() => { commandKey.current = randomId(); }, [reason, action]);
  async function submit() { if (!record || busy || !reason.trim()) return; setBusy(true); setError(null); try { await api.recordsRequest(`/issues/${encodeURIComponent(issue.id)}/actions?${query}`, 'POST', { action, reason: reason.trim() }, { 'If-Match': `"${record.revision}"`, 'Idempotency-Key': commandKey.current }); setReason(''); onUpdated(); } catch (caught) { setError(message(caught)); } finally { setBusy(false); } }
  return <article className="records-issue"><div className="records-issue-heading"><Glyph name="alert" size={20}/><div><strong>{issue.title || displayState(issue.category)}</strong><span>{displayState(issue.category)} · {issue.subjectId || issue.entityId || 'Record'} · {displayState(issue.severity)}</span></div><Status value={issue.status || issue.state}/></div>{issue.description && <p>{issue.description}</p>}{issue.actions?.length ? <details><summary>{issue.actions.length} review action{issue.actions.length === 1 ? '' : 's'}</summary><ol className="records-review-history">{issue.actions.map(entry => <li key={entry.id}><strong>{displayState(entry.action)}</strong><p>{entry.reason}</p><small>{entry.actorId} · {date(entry.createdAt)}</small></li>)}</ol></details> : null}
    {issue.assignment && <p>Review assignment: {issue.assignment.membershipId || 'cleared'}{issue.assignment.membershipId && !issue.assignment.membershipActive ? ' (membership is no longer active)' : ''}</p>}{canAssign && record && <IssueAssignment api={api} proofId={record.proofId} issueId={issue.id} revision={record.revision} query={query} onUpdated={onUpdated}/>}
    {canReview && record && <details className="records-review-form"><summary>Add a review action</summary><label>Action<select value={action} onChange={event => setAction(event.target.value)}><option value="note">Add review note</option><option value="acknowledge">Acknowledge issue</option><option value="resolve">Resolve with a reason</option><option value="reopen">Reopen with a reason</option></select></label><label>Reason<textarea value={reason} maxLength={1000} onChange={event => setReason(event.target.value)} placeholder="Explain what you reviewed and why this action is appropriate." rows={3}/></label><p>Review actions preserve the original evidence and source observations.</p>{error && <p role="alert" className="records-error-text">{error}</p>}<button className="records-button secondary" disabled={busy || !reason.trim()} onClick={() => void submit()}>{busy ? 'Saving…' : 'Save review action'}</button></details>}
  </article>;
}

function RecordDetailScreen({ api, organization, params, id, revision, onRefresh, onGo, storageScope }: { storageScope: string; api: PackProofApi; organization: RecordOrganization; params: URLSearchParams; id: string; revision: number; onRefresh: () => void; onGo: Go }) {
  const query = scopeQuery(organization, params.get('locationId')).toString();
  const result = useRemote<RecordDetail>(api, `/${encodeURIComponent(id)}?${query}`, revision);
  const [additional, setAdditional] = useState<{ boundary: RecordDetail; evidence: RecordEvidence[]; timeline: RecordTimelineEntry[]; evidenceCursor: string | null; timelineCursor: string | null; busy: boolean; error: string | null } | null>(null);
  const currentDetail = useRef<RecordDetail | null>(null); currentDetail.current = result.data;
  const [tab, setTab] = useState('summary'), [entity, setEntity] = useState('all'), [workflowReason, setWorkflowReason] = useState(''), [actionError, setActionError] = useState<string | null>(null), [actionBusy, setActionBusy] = useState(false);
  const workflowKey = useRef(randomId());
  useEffect(() => { workflowKey.current = randomId(); }, [workflowReason]);
  useEffect(() => { setTab('summary'); setEntity('all'); setActionError(null); }, [id, query]);
  if (result.loading && !result.data) return <Loading>Opening shipping record…</Loading>;
  if (result.error) return <Failure error={result.error} onRetry={onRefresh}/>;
  const detail = result.data; if (!detail) return null;
  const record = detail.record;
  const pages = additional?.boundary === detail ? additional : { boundary: detail, evidence: [] as RecordEvidence[], timeline: [] as RecordTimelineEntry[], evidenceCursor: detail.evidenceNextCursor || null, timelineCursor: detail.timelineNextCursor || null, busy: false, error: null };
  const allEvidence = [...detail.evidence, ...pages.evidence], allTimeline = [...detail.timeline, ...pages.timeline];
  async function loadMore(kind: 'evidence' | 'timeline') { const cursor = kind === 'evidence' ? pages.evidenceCursor : pages.timelineCursor; if (!cursor || pages.busy) return; setAdditional({ ...pages, busy: true, error: null }); try { const page = await api.recordsRequest<{ evidence?: RecordEvidence[]; timeline?: RecordTimelineEntry[]; nextCursor: string | null }>(`/${encodeURIComponent(id)}/${kind}?${query}&cursor=${encodeURIComponent(cursor)}&limit=50`); if (currentDetail.current !== detail) return; setAdditional({ ...pages, evidence: [...pages.evidence, ...(page.evidence || [])], timeline: [...pages.timeline, ...(page.timeline || [])], [kind === 'evidence' ? 'evidenceCursor' : 'timelineCursor']: page.nextCursor, busy: false, error: null }); } catch (caught) { if (currentDetail.current === detail) setAdditional({ ...pages, busy: false, error: message(caught) }); } }
  const entities = [...new Set([record.id, ...detail.relationships.map(item => item.id), ...allTimeline.map(item => item.subjectId || item.entityId).filter((value): value is string => !!value), ...detail.requirements.map(item => item.subjectId || item.entityId).filter((value): value is string => !!value), ...allEvidence.flatMap(item => item.subjectIds || (item.entityId ? [item.entityId] : []))])];
  const entityLabel = (value: string) => { const relationship = detail.relationships.find(item => item.id === value); return relationship?.label || (relationship ? `${displayState(relationship.kind || relationship.type || 'Entity')}${relationship.externalReference ? ` - ${String(relationship.externalReference)}` : ''}` : value === record.id ? 'Shipment record' : value); };
  const scopedIssues = detail.issues.filter(issue => entity === 'all' || (issue.subjectId || issue.entityId) === entity);
  const scopedEvidence = allEvidence.filter(item => entity === 'all' || item.subjectIds?.includes(entity) || item.entityId === entity);
  const scopedTimeline = allTimeline.filter(item => entity === 'all' || (item.subjectId || item.entityId) === entity);
  const scopedRequirements = detail.requirements.filter(item => entity === 'all' || (item.subjectId || item.entityId) === entity);
  async function workflow() { if (!workflowReason.trim() || actionBusy) return; setActionBusy(true); setActionError(null); try { await api.recordsRequest(`/${encodeURIComponent(id)}/${record.lifecycle === 'closed' ? 'reopen' : 'close'}?${query}`, 'POST', { reason: workflowReason.trim() }, { 'If-Match': `"${record.revision}"`, 'Idempotency-Key': workflowKey.current }); setWorkflowReason(''); onRefresh(); } catch (caught) { setActionError(message(caught)); } finally { setActionBusy(false); } }
  return <>
    <LocalLink className="records-back" href={recordsPath('records', params)} onGo={path => { const previous = window.history.state?.ppFrom; if (typeof previous === 'string' && /^\/app\/records(?:\?|$)/.test(previous)) window.history.back(); else onGo(path); }}>← Back to records</LocalLink>
    <header className="records-page-heading"><div><span className="records-eyebrow">SHIPPING RECORD · REVISION {record.revision}</span><h1>{record.reference || record.id}</h1><p>{record.title || 'Shipping evidence record'}</p></div><div className="records-actions"><LocalLink className="records-button secondary" href={`/proofs/${encodeURIComponent(record.proofId)}`} onGo={onGo}>Open original Proof<Glyph size={16}/></LocalLink><button className="records-button secondary" onClick={onRefresh} disabled={result.loading}>Refresh</button></div></header>
    <RecordPackageDownload api={api} proofId={record.proofId} organizationId={organization.id} environment={organization.environment} canExport={detail.capabilities.export === true}/>
    <div className="records-detail-meta"><span><Glyph name="pin" size={15}/>{organization.name}{record.locationId ? ` · ${organization.locations.find(location => location.id === record.locationId)?.name || record.locationId}` : ''}</span><span><Glyph name="link" size={15}/>{record.sourceName || 'Source not specified'}</span><Status value={record.lifecycle}/>{organization.environment !== 'live' && <Status value="sandbox">Sandbox</Status>}<span>Last PackProof update {date(record.updatedAt)}</span></div>
    {detail.issues.some(issue => (issue.status || issue.state) !== 'resolved') && <section className="records-notice warning"><Glyph name="alert"/><div><strong>{detail.issues.filter(issue => (issue.status || issue.state) !== 'resolved').length} issue(s) need review</strong><p>Inspect the affected entity and source before resolving an issue.</p><button className="records-text-button" onClick={() => setTab('review')}>Review issues</button></div></section>}
    <div className="records-detail-layout"><aside className="records-entities" aria-label="Shipment entities"><h2>Entities</h2><button aria-pressed={entity === 'all'} onClick={() => setEntity('all')}>All entities<span>{entities.length}</span></button>{entities.map(value => <button key={value} aria-pressed={entity === value} onClick={() => setEntity(value)} title={value}><Glyph name="box" size={16}/><span>{entityLabel(value)}</span></button>)}</aside>
      <section className="records-detail-content">{pages.error && <div className="records-notice error" role="alert">{pages.error}</div>}<div className="records-detail-tabs" aria-label="Record sections">{[['summary', 'Summary'], ['timeline', 'Timeline'], ['evidence', 'Evidence'], ['requirements', 'Requirements'], ['review', 'Review history'], ['packages', 'Packages & access'], ['audit', 'Technical & audit']].map(([key, label]) => <button key={key} aria-pressed={tab === key} onClick={() => setTab(key)}>{label}</button>)}</div><p className="records-active-scope">Showing {entity === 'all' ? 'all entities' : entityLabel(entity)}. This selection applies to the timeline, evidence, requirements, and issues.</p>
        {tab === 'summary' && <><QuantitySummary relationships={detail.relationships} selectedEntity={entity}/><div className="records-summary-grid"><section className="records-panel"><h2>What has arrived</h2><dl className="records-facts"><div><dt>Evidence files</dt><dd>{scopedEvidence.length}{pages.evidenceCursor ? ' loaded' : ''}</dd></div><div><dt>Source events</dt><dd>{scopedTimeline.length}{pages.timelineCursor ? ' loaded' : ''}</dd></div><div><dt>Requirements</dt><dd>{scopedRequirements.filter(item => ['satisfied', 'waived'].includes(item.status || item.state || '')).length} of {scopedRequirements.length} met</dd></div><div><dt>Tracking</dt><dd>{record.trackingNumber || 'Not supplied'}</dd></div><div><dt>Carrier</dt><dd>{record.carrier || 'Not supplied'}</dd></div></dl><button className="records-text-button" onClick={() => setTab('evidence')}>Inspect the evidence<Glyph size={16}/></button></section><section className="records-panel"><h2>Checks stay separate</h2><dl className="records-facts"><div><dt>Workflow</dt><dd><Status value={record.lifecycle}/></dd></div><div><dt>Finalized capture package</dt><dd><Status value={record.integrity}/></dd></div><div><dt>Review</dt><dd><Status value={record.review}/></dd></div><div><dt>Source freshness</dt><dd><Status value={detail.sourceHealth.state}/></dd></div></dl><p className="records-muted">{detail.assurance?.explanation || 'A core package covers the original files and history listed in its frozen manifest. Operational notes and later review actions are separate from that signed inventory.'} Physical condition is not established by a file-integrity check.</p></section></div><section className="records-panel"><h2>What needs attention</h2>{scopedIssues.length ? scopedIssues.map(issue => <IssueCard key={issue.id} issue={issue} record={record} api={api} query={query} canReview={!!detail.capabilities.review} canAssign={['OWNER','ADMIN'].includes(organization.role)} onUpdated={onRefresh}/>) : <p>No issues are recorded for this entity scope. Review the policy requirements and source freshness separately.</p>}</section></>}
        {tab === 'timeline' && <section className="records-panel"><h2>Recorded history</h2><p className="records-muted">Commit history is preserved in server order. Source-reported times may differ from PackProof receipt times.</p>{scopedTimeline.length ? <ol className="records-timeline">{scopedTimeline.map(event => <li key={event.id}><span className="records-timeline-icon"><Glyph name={String(event.type).toLowerCase().includes('evidence') ? 'film' : 'clock'} size={18}/></span><div><strong>{event.title || event.summary || displayState(event.type || event.eventType)}</strong><p>{event.description || sourceLabel(event.source)}</p><small>Received {date(event.receivedAt || event.createdAt)}</small>{event.reportedAt && <small>Source reported {date(event.reportedAt)}{event.receivedAt && new Date(event.receivedAt).getTime() - new Date(event.reportedAt).getTime() > 3600000 ? ' · delayed arrival' : ''}</small>}<details><summary>Source details</summary><dl className="records-facts"><div><dt>Event</dt><dd><code>{event.id}</code></dd></div><div><dt>Entity</dt><dd>{event.subjectId || event.entityId || 'Record'}</dd></div><div><dt>Source</dt><dd>{sourceLabel(event.source)}</dd></div></dl>{event.data && <pre>{JSON.stringify(event.data, null, 2)}</pre>}</details></div></li>)}</ol> : <p>{pages.timelineCursor ? 'No source events match this scope in the loaded history. Load more history to continue.' : 'No source events are available in this entity scope.'}</p>}{pages.timelineCursor && <button className="records-button secondary" disabled={pages.busy} onClick={() => void loadMore('timeline')}>Load more history</button>}</section>}
        {tab === 'evidence' && <><section className="records-panel"><h2>Original evidence</h2><p className="records-muted">Source attribution and receipt metadata belong to each file. Originals remain separate from any derivative.</p>{scopedEvidence.length ? <div className="records-evidence-grid">{scopedEvidence.map((evidence, index) => <EvidenceCard key={evidence.id || evidence.evidenceId || index} evidence={evidence}><RecordMedia api={api} proofId={record.proofId} organizationId={organization.id} environment={organization.environment} evidence={evidence} canDownload={detail.capabilities.downloadOriginal === true}/></EvidenceCard>)}</div> : <Empty title="No evidence files in this scope">{pages.evidenceCursor ? 'No files match this scope in the loaded evidence. Load more evidence to continue.' : 'Choose another entity or review the missing requirements. A source status alone is not a photo or a handoff document.'}</Empty>}{pages.evidenceCursor && <button className="records-button secondary" disabled={pages.busy} onClick={() => void loadMore('evidence')}>Load more evidence</button>}</section><SourceArtifacts key={`sources-${organization.id}.${organization.environment}.${record.proofId}`} api={api} proofId={record.proofId} organizationId={organization.id} environment={organization.environment} entities={entities.map(value => ({ id: value, label: entityLabel(value) }))} canUpload={detail.capabilities.edit === true} revision={revision} storageScope={storageScope} onUpdated={onRefresh} selectedEntity={entity}/></>}
        {tab === 'requirements' && ['OWNER','ADMIN'].includes(organization.role) && <RequirementTemplates key={record.proofId} api={api} proofId={record.proofId} organizationId={organization.id} environment={organization.environment} recordRevision={record.revision} entities={entities.map(value=>({id:value,label:entityLabel(value)}))} onUpdated={onRefresh}/>}
        {tab === 'requirements' && <section className="records-panel"><h2>Evidence requirements</h2>{scopedRequirements.length ? <div className="records-requirements">{scopedRequirements.map((requirement, index) => <article key={requirement.id || index}><Status value={requirement.status || requirement.state}/><div><strong>{requirement.title || requirement.label || 'Evidence requirement'}</strong><p>{requirement.description || `${displayState(requirement.stage)} · ${requirement.subjectId || requirement.entityId || 'Record'}`}</p><small>Template {requirement.templateVersion || 'Not reported'}{requirement.dueAt ? ` · Due ${date(requirement.dueAt)}` : ''}</small>{requirement.waiver && <p>Waiver: {requirement.waiver.reason}</p>}<small>{requirement.evidenceIds?.length ? `${requirement.evidenceIds.length} linked evidence file(s)` : 'No matching evidence linked'}</small>{detail.capabilities.waive && !requirement.waiver && requirement.id && <RequirementWaiverControl api={api} record={record} query={query} requirementId={requirement.id} onUpdated={onRefresh}/>}</div></article>)}</div> : <p>No requirement policy is assigned in this scope. This does not establish complete evidence.</p>}</section>}
        {tab === 'review' && <section className="records-panel"><h2>Issues &amp; review history</h2><p className="records-muted">Missing evidence, contradictory sources, processing failures, and integrity failures need different remedies. Resolution records a review decision.</p>{scopedIssues.length ? scopedIssues.map(issue => <IssueCard key={issue.id} issue={issue} record={record} api={api} query={query} canReview={!!detail.capabilities.review} canAssign={['OWNER','ADMIN'].includes(organization.role)} onUpdated={onRefresh}/>) : <p>No review issues in this scope.</p>}</section>}
        {tab === 'packages' && <><CanonicalExports api={api} proofId={record.proofId} organizationId={organization.id} environment={organization.environment} enabled={['OWNER', 'ADMIN'].includes(organization.role)} storageScope={storageScope}/><OperationalSnapshots key={`snapshots-${organization.id}.${organization.environment}.${record.proofId}`} api={api} proofId={record.proofId} organizationId={organization.id} environment={organization.environment} recordRevision={record.revision} enabled={detail.capabilities.operationalSnapshots === true} storageScope={storageScope}/><SnapshotShares key={`shares-${organization.id}.${organization.environment}.${record.proofId}`} api={api} proofId={record.proofId} organizationId={organization.id} environment={organization.environment} enabled={['OWNER','ADMIN'].includes(organization.role)}/></>}
        {tab === 'audit' && <section className="records-panel"><h2>Identity &amp; audit</h2><dl className="records-facts"><div><dt>Canonical Proof</dt><dd><code>{record.proofId}</code></dd></div><div><dt>Organization</dt><dd><code>{record.organizationId}</code></dd></div><div><dt>Environment</dt><dd>{organization.environment === 'live' ? 'Production' : displayState(organization.environment)}</dd></div><div><dt>Revision</dt><dd>{record.revision}</dd></div><div><dt>Created</dt><dd>{date(record.createdAt)}</dd></div><div><dt>Committed update</dt><dd>{date(record.updatedAt)}</dd></div></dl><p>Historical imports retain their original assurance. A later digest does not retroactively establish when a source captured the original.</p></section>}
        {!!detail.capabilities.review && <RecordReviewControl key={`review-${record.revision}`} api={api} record={record} query={query} onUpdated={onRefresh}/>}
        {!!detail.capabilities.edit && <RecordMetadataControl key={`metadata-${record.revision}`} api={api} record={record} query={query} onUpdated={onRefresh}/>}
        {!!detail.capabilities.edit && <details className="records-panel records-workflow-action"><summary>{record.lifecycle === 'closed' ? 'Reopen workflow' : 'Close workflow'}</summary><p>Workflow changes preserve accepted evidence and review history.</p><label>Reason<textarea value={workflowReason} onChange={event => setWorkflowReason(event.target.value)} maxLength={2000} rows={2}/></label>{actionError && <p className="records-error-text" role="alert">{actionError}</p>}<button className="records-button secondary" disabled={actionBusy || !workflowReason.trim()} onClick={() => void workflow()}>{record.lifecycle === 'closed' ? 'Reopen with reason' : 'Close with reason'}</button></details>}
      </section>
    </div>
  </>;
}
function EvidenceCard({ evidence, children }: { evidence: RecordEvidence; children: ReactNode }) { return <article className="records-evidence-card"><span className="records-evidence-icon"><Glyph name={String(evidence.contentType).startsWith('video/') ? 'film' : 'file'} size={29}/></span><h3>{evidence.name || evidence.filename || evidence.originalFileName || displayState(evidence.type || evidence.evidenceType)}</h3><Status value={evidence.state || evidence.processingState || evidence.validationStatus || evidence.status}/><dl className="records-facts"><div><dt>Source</dt><dd>{sourceLabel(evidence.source)}</dd></div><div><dt>Received</dt><dd>{date(evidence.receivedAt || evidence.createdAt)}</dd></div><div><dt>File</dt><dd>{evidence.contentType || evidence.mimeType || 'Type not reported'} · {(evidence.byteSize ?? evidence.sizeBytes)?.toLocaleString() ?? 'Unknown'} bytes</dd></div><div><dt>Original</dt><dd>{evidence.original === true ? 'Original file' : evidence.original === false ? 'Derivative' : 'Not specified'}</dd></div></dl><details><summary>File verification details</summary><code>{evidence.sha256 || 'Digest not yet established'}</code><small>Artifact {evidence.id || evidence.evidenceId}</small></details>{children}</article>; }

function AttentionScreen({ api, organization, params, revision, onRefresh, onGo }: { api: PackProofApi; organization: RecordOrganization; params: URLSearchParams; revision: number; onRefresh: () => void; onGo: Go }) {
  const queryParams = scopeQuery(organization, params.get('locationId')); if (params.get('cursor')) queryParams.set('cursor', params.get('cursor')!); const query = queryParams.toString(), result = useRemote<{ issues: RecordIssue[]; nextCursor?: string | null }>(api, `/issues?${query}`, revision);
  const [category, setCategory] = useState('all'); const categories = [...new Set(result.data?.issues.map(issue => issue.category || 'unknown') || [])]; const issues = result.data?.issues.filter(issue => category === 'all' || issue.category === category) || [];
  return <><header className="records-page-heading"><div><span className="records-eyebrow">EXCEPTION-FIRST REVIEW</span><h1>Needs attention</h1><p>Go directly to the affected record, entity, and source.</p></div></header><section className="records-panel"><div className="records-list-controls"><label>Issue category<select value={category} onChange={event => setCategory(event.target.value)}><option value="all">All categories</option>{categories.map(value => <option key={value} value={value}>{displayState(value)}</option>)}</select></label><span className="records-muted">Unresolved issues on this page · selected permitted locations</span></div>{result.error ? <Failure error={result.error} onRetry={onRefresh}/> : result.loading && !result.data ? <Loading>Loading issues…</Loading> : issues.length ? issues.map(issue => <div className="records-queue-item" key={issue.id}><IssueCard issue={issue} api={api} query={query} canReview={false} onUpdated={onRefresh}/>{(issue.proofId || issue.recordId) && <LocalLink className="records-button secondary" href={recordsPath('records', params, {}, issue.proofId || issue.recordId)} onGo={onGo}>Open affected record<Glyph size={16}/></LocalLink>}</div>) : <Empty title="No matching issues">No unresolved issues match this page and category. Check connection health separately to understand whether source data is current.</Empty>}{(params.get('cursor') || result.data?.nextCursor) && <div className="records-pagination"><button className="records-button secondary" disabled={!params.get('cursor') || result.loading} onClick={() => onGo(recordsPath('attention', params, { cursor: null }))}>First page</button><span>Bounded results from up to 100 matching records per page</span><button className="records-button secondary" disabled={!result.data?.nextCursor || result.loading} onClick={() => onGo(recordsPath('attention', params, { cursor: result.data?.nextCursor || null }))}>Next page</button></div>}</section></>;
}
function ConnectionsScreen({ api, organization, params, revision, onRefresh, onGo }: { api: PackProofApi; organization: RecordOrganization; params: URLSearchParams; revision: number; onRefresh: () => void; onGo: Go }) {
  const query = scopeQuery(organization, params.get('locationId')).toString(), result = useRemote<{ connections: RecordConnection[]; currentNeedsAction?: number }>(api, `/connections?${query}`, revision);
  return <><header className="records-page-heading"><div><span className="records-eyebrow">CURRENT SOURCE HEALTH</span><h1>Connections</h1><p>Understand what is arriving and where to act next.</p></div><LocalLink className="records-button" href={recordsPath('setup', params)} onGo={onGo}><Glyph name="plus" size={17}/>Add a source</LocalLink></header><p className="records-cohort">Current connection state for permitted locations. This view is independent of record creation dates.</p>{result.error ? <Failure error={result.error} onRetry={onRefresh}/> : result.loading && !result.data ? <Loading>Checking source health…</Loading> : result.data?.connections.length ? <div className="records-connections">{result.data.connections.map((connection, index) => { const health = typeof connection.health === 'object' ? connection.health.state : connection.health; return <section className="records-panel" key={connection.id || connection.connectionId || index}><div className="records-connection-heading"><span className="records-connection-icon"><Glyph name="link" size={24}/></span><div><h2>{connection.name || connection.provider || 'Source connection'}</h2><p>{connection.accountName || String(connection.sourceReference || 'Account identity not supplied')}</p></div><Status value={health || connection.state || 'freshness_unknown'}>{connection.label ? String(connection.label) : undefined}</Status></div><dl className="records-facts"><div><dt>Authorization</dt><dd>{connection.status ? displayState(connection.status) : 'Not independently measured'}</dd></div><div><dt>Last successful contact</dt><dd>{date(connection.lastSuccessfulContactAt || (connection.lastSuccessfulSyncAt as string | null))}</dd></div><div><dt>Last usable event</dt><dd>{date(connection.lastUsableEventAt)}</dd></div><div><dt>Last watermark check</dt><dd>{date(connection.lastReconciliationAt || (connection.lastWatermarkCheckAt as string | null))}</dd></div><div><dt>Oldest queued work</dt><dd>{date(connection.oldestQueuedAt)}</dd></div><div><dt>Responsible owner</dt><dd>{connection.owner || 'Not assigned'}</dd></div></dl>{connection.availableData?.length ? <p>Available data: {connection.availableData.join(', ')}</p> : null}<p className="records-muted">{connection.reason || (connection.capabilities && typeof connection.capabilities === 'object' && 'reason' in connection.capabilities ? String(connection.capabilities.reason) : 'Authorization alone does not establish source freshness. Accepted records remain available if this connection is paused.')}</p>{['OWNER', 'ADMIN'].includes(organization.role) && !['csv', 'spreadsheet', 'file'].includes(String(connection.provider).toLowerCase()) && (connection.id || connection.connectionId) && <ConnectionActions api={api} id={String(connection.id || connection.connectionId)} query={query} paused={connection.state === 'paused'} onUpdated={onRefresh}/>}</section>; })}</div> : <section className="records-panel"><Empty title="No automatic source is connected" action={<LocalLink className="records-button" href={recordsPath('setup', params)} onGo={onGo}>Choose a source</LocalLink>}>Spreadsheet imports are one-time events. Continuous sync requires a supported, authorized connection that passes its source checks.</Empty></section>}</>;
}
function ExportsScreen({ api, organization, params, revision, onRefresh, onGo }: { api: PackProofApi; organization: RecordOrganization; params: URLSearchParams; revision: number; onRefresh: () => void; onGo: Go }) {
  const query = scopeQuery(organization, params.get('locationId')).toString(), result = useRemote<{ exports: RecordExport[] }>(api, `/exports?${query}`, revision);
  return <><header className="records-page-heading"><div><span className="records-eyebrow">PORTABLE EVIDENCE</span><h1>Evidence packages</h1><p>Track the packages prepared from authorized record snapshots.</p></div></header><CanonicalExportHistory api={api} organizationId={organization.id} environment={organization.environment} enabled={['OWNER', 'ADMIN'].includes(organization.role)} revision={revision}/><div className="records-notice neutral"><Glyph name="info"/><p>Download availability and share access have separate expiry dates. Downloaded copies remain with their recipients.</p></div><section className="records-panel">{result.error ? <Failure error={result.error} onRetry={onRefresh}/> : result.loading && !result.data ? <Loading>Loading evidence packages…</Loading> : result.data?.exports.length ? <div className="records-table-wrap"><table><thead><tr><th scope="col">Package</th><th scope="col">State</th><th scope="col">Created</th><th scope="col">Download available until</th><th scope="col">Action</th></tr></thead><tbody>{result.data.exports.map((item, index) => { const url = safeDownloadUrl(item.downloadUrl); return <tr key={item.id || item.exportId || index}><td><strong>{item.reference || item.id || item.exportId}</strong>{item.omissions?.length ? <small>{item.omissions.length} omission(s) declared</small> : null}</td><td><Status value={item.state || item.status}/></td><td>{date(item.createdAt)}</td><td>{date(item.downloadAvailableUntil || item.expiresAt)}</td><td>{url ? <a className="records-button secondary" href={url} rel="noreferrer">Download<Glyph name="download" size={16}/></a> : (item.proofId || item.recordId) ? <LocalLink className="records-text-button" href={recordsPath('records', params, {}, item.proofId || item.recordId)} onGo={onGo}>View record</LocalLink> : 'Availability not reported'}</td></tr>; })}</tbody></table></div> : <Empty title="No evidence packages yet" action={<LocalLink className="records-button secondary" href={recordsPath('records', params)} onGo={onGo}>Find a shipping record</LocalLink>}>Open a record and review its snapshot and available evidence. Package actions appear when your role and the record’s assurance profile permit them.</Empty>}</section></>;
}

function SetupScreen({ api, organization, session, params, canImport, onGo }: { api: PackProofApi; organization: RecordOrganization; session: WebSession; params: URLSearchParams; canImport: boolean; onGo: Go }) {
  const [path, setPath] = useState('csv');
  return <><header className="records-page-heading"><div><span className="records-eyebrow">CONNECT YOUR OPERATION</span><h1>Where does your shipping information live?</h1><p>Start with a spreadsheet or review the scope of a supported connection.</p></div></header><div className="records-entry-paths"><button aria-pressed={path === 'csv'} onClick={() => setPath('csv')}><Glyph name="file" size={25}/><strong>Upload a spreadsheet</strong><span>Available</span><p>Preview columns, correct rows, and create records from your CSV.</p></button><button aria-pressed={path === 'connector'} onClick={() => setPath('connector')}><Glyph name="link" size={25}/><strong>Connect a supported source</strong><span>Pilot scope</span><p>Review account access, supported data, and workspace readiness.</p></button><button aria-pressed={path === 'assisted'} onClick={() => setPath('assisted')}><Glyph name="settings" size={25}/><strong>Get help with another system</strong><span>Request connection</span><p>Scope an ERP, WMS, TMS, or existing evidence source.</p></button></div>
    {path === 'csv' && (canImport ? <ImportWizard key={`${organization.id}.${organization.environment}`} api={api} organizationId={organization.id} environment={organization.environment} storageScope={`${session.apiBaseUrl}.${session.userId}`} onViewRecords={() => onGo(recordsPath('records', params, { cursor: null }))} onOpenRecord={id => onGo(recordsPath('records', params, {}, id))}/> : <section className="records-panel"><Empty title="Import access is required">Your workspace administrator can enable the appropriate role and activation cohort. You can continue reviewing the records you are authorized to see.</Empty></section>)}
    {path === 'connector' && <section className="records-panel"><h2>Review the connection before activation</h2><p>Supported data and synchronization are specific to the provider and your workspace. A linked account is ready for sync only after a successful read, mapping, accepted ingestion, and visible record.</p><div className="records-actions"><LocalLink className="records-button secondary" href={recordsPath('connections', params)} onGo={onGo}>Review this workspace’s sources</LocalLink><LocalLink className="records-button secondary" href="/stores" onGo={onGo}>Manage linked accounts</LocalLink></div><p className="records-muted">Linking a personal marketplace account does not grant a partner access to this workspace. Workspace pilot activation remains explicit.</p></section>}
    {path === 'assisted' && <section className="records-panel"><h2>Review your connection plan</h2><p>Share the system name, supported export or API, desired locations, and evidence types with the PackProof integration owner. Include only documentation or sample data you are authorized to share.</p><dl className="records-facts"><div><dt>Integration owner</dt><dd>PackProof integration support</dd></div><div><dt>Next step</dt><dd>Confirm source access, mapping, maintenance owner, and a bounded test cohort.</dd></div></dl><a className="records-button secondary" href={`mailto:admin@thepackproof.com?subject=${encodeURIComponent(`Connection assessment: ${organization.name}`)}`}>Prepare connection request<Glyph name="mail" size={17}/></a></section>}
  </>;
}

const TOUR = [
  { title: 'Find the shipping record', body: 'Search a shipment, order, tracking number, or record ID. Your workspace, location, and environment stay visible.' },
  { title: 'Inspect what needs attention', body: 'Missing evidence, a conflicting source, and a file integrity failure have different meanings. Open the issue to see the affected entity.' },
  { title: 'Open the evidence', body: 'Select a shipment entity to scope its timeline, evidence, and requirements together. File metadata explains its source and receipt time.' },
  { title: 'Check the source', body: 'Connections describe source freshness separately from record coverage. An authorized account may still need mapping or recovery.' },
  { title: 'Review a package before sharing', body: 'Evidence packages preserve a selected snapshot. Review included files, omissions, assurance, and download availability. Access remains permission scoped.' },
];
export default function RecordsPortal({ api, session, href, onGo, onSignOut, adminAllowed = false, developerAllowed = false }: { api: PackProofApi; session: WebSession; href: string; onGo: Go; onSignOut: () => void; adminAllowed?: boolean; developerAllowed?: boolean }) {
  const connectApproval = /^\/app\/records\/connect(?:\/approve)?\/?$/.test(new URL(href, 'https://packproof.local').pathname);
  const { section, id, params } = recordsRoute(href), { scheme, setPreference } = useTheme();
  const [revision, setRevision] = useState(0), [tour, setTour] = useState<number | null>(null), [tourDone, setTourDone] = useState(false);
  const tourKey = `packproof.records.tour.${session.apiBaseUrl}.${session.userId}`;
  const contextParams = new URLSearchParams(); for (const key of ['organizationId', 'environment']) { const value = params.get(key); if (value) contextParams.set(key, value); }
  const context = useRemote<RecordsContext>(api, `/context${contextParams.size ? `?${contextParams}` : ''}`, revision);
  useEffect(() => { try { setTourDone(localStorage.getItem(tourKey) === 'done'); if (localStorage.getItem(APPEARANCE_STORAGE_KEY) === null) setPreference('light'); } catch { /* Defaults remain usable when storage is unavailable. */ } }, [tourKey, setPreference]);
  const requestedId = params.get('organizationId') || context.data?.selectedOrganizationId;
  const organization = context.data?.organizations.find(value => value.id === requestedId && (!params.get('environment') || value.environment === params.get('environment')));
  const selectedLocation = params.get('locationId'), locationAllowed = !selectedLocation || !!organization?.locations.some(location => location.id === selectedLocation);
  const scopedParams = new URLSearchParams(params); if (organization) { scopedParams.set('organizationId', organization.id); scopedParams.set('environment', organization.environment); }
  const refresh = () => setRevision(value => value + 1);
  const nav: Array<[RecordsSection, string, string]> = [['records', 'Records', 'file'], ['attention', 'Needs attention', 'alert'], ['connections', 'Connections', 'link'], ['exports', 'Exports', 'download'], ['settings', 'Settings', 'settings']];
  const leaveTour = () => { setTour(null); setTourDone(true); try { localStorage.setItem(tourKey, 'done'); } catch { /* Optional preference. */ } };
  const goSection = (target: RecordsSection) => recordsPath(target, scopedParams, { cursor: null });
  return <div className="records-shell">
    <a href="#records-main" className="records-skip-link">Skip to records workspace</a>
    <aside className="records-sidebar"><LocalLink href="/app/records" onGo={onGo} className="records-brand"><img src="/brand/packproof-symbol.svg" width="35" height="35" alt=""/><span>PackProof<small>EVIDENCE WORKSPACE</small></span></LocalLink><p className="records-nav-label">YOUR OPERATION</p><nav aria-label="Records workspace">{nav.map(([target, label, icon]) => <LocalLink key={target} href={goSection(target)} onGo={onGo} aria-current={section === target || target === 'records' && section === 'setup' ? 'page' : undefined}><Glyph name={icon} size={19}/>{label}</LocalLink>)}</nav><div className="records-sidebar-bottom"><button onClick={() => setTour(0)}><Glyph name="info" size={18}/>Help &amp; guided tour</button><LocalLink href="/capture/home" onGo={onGo}><Glyph name="film" size={18}/>Capture workspace</LocalLink>{developerAllowed && <LocalLink href="/developer" onGo={onGo}><Glyph name="code" size={18}/>Developers</LocalLink>}{adminAllowed && <LocalLink href="/admin" onGo={onGo}><Glyph name="grid" size={18}/>Administration</LocalLink>}<button onClick={() => setPreference(scheme === 'dark' ? 'light' : 'dark')}><Glyph name={scheme === 'dark' ? 'sun' : 'moon'} size={18}/>{scheme === 'dark' ? 'Light appearance' : 'Dark appearance'}</button><div className="records-profile"><span>{(session.displayName || session.username || 'P').slice(0, 1).toUpperCase()}</span><div><strong>{session.displayName || session.username || 'Your account'}</strong><button onClick={onSignOut}>Sign out</button></div></div></div></aside>
    <div className="records-workspace"><header className="records-topbar"><div className="records-scope"><label>Workspace<select aria-label="Organization workspace" value={organization ? `${organization.id}:${organization.environment}` : ''} onChange={event => { const next = context.data?.organizations.find(value => `${value.id}:${value.environment}` === event.target.value); if (next) { const path = recordsPath('records', params, { organizationId: next.id, environment: next.environment, locationId: null, cursor: null, q: null }); onGo(connectApproval ? path.replace('/app/records?', '/app/records/connect/approve?') : path); } }}><option value="" disabled>Select a workspace</option>{context.data?.organizations.map(value => <option key={`${value.id}:${value.environment}`} value={`${value.id}:${value.environment}`}>{value.name} · {value.environment === 'live' ? 'Production' : displayState(value.environment)}</option>)}</select></label>{organization && !connectApproval && <label>Location<select value={selectedLocation || ''} onChange={event => onGo(recordsPath(section, scopedParams, { locationId: event.target.value || null, cursor: null }, id || undefined))}><option value="">All permitted locations</option>{organization.locations.map(location => <option key={location.id} value={location.id}>{location.name}</option>)}</select></label>}</div><div className="records-topbar-right"><button className="records-icon-button" aria-label={`Switch to ${scheme === 'dark' ? 'light' : 'dark'} appearance`} onClick={() => setPreference(scheme === 'dark' ? 'light' : 'dark')}><Glyph name={scheme === 'dark' ? 'sun' : 'moon'} size={18}/></button>{organization && <Status value={organization.environment === 'live' ? 'production' : 'sandbox'}>{organization.environment === 'live' ? 'Production' : 'Sandbox'}</Status>}<button className="records-icon-button" aria-label="Refresh records workspace" title="Refresh records workspace" onClick={refresh}><Glyph name="activity" size={18}/></button></div></header>
      <main id="records-main" className="records-main" tabIndex={-1} aria-busy={context.loading}>
        {context.error ? <Failure error={context.error} onRetry={refresh}/> : context.loading && !context.data ? <Loading>Opening your authorized workspace…</Loading> : !organization ? <><section className="records-panel"><Empty title={requestedId ? 'Workspace unavailable' : 'Your workspace is not ready yet'} action={<div className="records-actions"><LocalLink className="records-button secondary" href="/sample-proof" onGo={onGo}>Explore a labeled sample</LocalLink><LocalLink className="records-button secondary" href="/account" onGo={onGo}>Open account settings</LocalLink></div>}>{requestedId ? 'The requested organization or environment is not available to this account. Choose a permitted workspace above.' : 'Ask your workspace owner for an invitation or contact PackProof to complete workspace activation. Sample exploration remains separate from production.'}</Empty></section>{!requestedId && <WorkspaceRequest api={api} scope={`${session.apiBaseUrl}.${session.userId}`} onSubmitted={refresh}/>}</> : !locationAllowed ? <section className="records-panel"><Empty title="Location access unavailable" action={<button className="records-button secondary" onClick={() => onGo(recordsPath('records', scopedParams, { locationId: null, cursor: null }))}>Use permitted locations</button>}>This location is not in your current workspace access. Choose an authorized location.</Empty></section> : !organization.enabled || !context.data?.capabilities.records ? <section className="records-panel"><Empty title="Waiting for workspace activation" action={<LocalLink className="records-button secondary" href="/sample-proof" onGo={onGo}>Explore a labeled sample</LocalLink>}>Registration and API activation are separate. Your workspace administrator and PackProof must complete the entitlement and release checks before production ingestion is available.</Empty></section> : <>
          {!connectApproval && !tourDone && section === 'records' && !id && <div className="records-welcome"><div><strong>New to your evidence workspace?</strong><p>Take a short tour, then connect or import your first shipment.</p></div><div className="records-actions"><button className="records-button secondary" onClick={() => setTour(0)}>Show me around</button><button className="records-text-button" onClick={leaveTour}>Dismiss</button></div></div>}
          {connectApproval && <AgentApproval key={`${organization.id}.${organization.environment}.${params.get('enrollmentId') || params.get('installationId')}`} api={api} organizationId={organization.id} environment={organization.environment} params={scopedParams} canManage={['OWNER', 'ADMIN'].includes(organization.role)}/>}
          {!connectApproval && section === 'records' && (id ? <RecordDetailScreen key={`${organization.id}.${organization.environment}.${id}`} api={api} organization={organization} params={scopedParams} id={id} revision={revision} onRefresh={refresh} onGo={onGo} storageScope={`${session.apiBaseUrl}.${session.userId}`}/> : <RecordsListScreen api={api} organization={organization} params={scopedParams} revision={revision} onGo={onGo} onRefresh={refresh}/>)}
          {section === 'attention' && <AttentionScreen api={api} organization={organization} params={scopedParams} revision={revision} onRefresh={refresh} onGo={onGo}/>}
          {section === 'connections' && <><ConnectionsScreen api={api} organization={organization} params={scopedParams} revision={revision} onRefresh={refresh} onGo={onGo}/><AgentConnections key={`${organization.id}.${organization.environment}`} api={api} organizationId={organization.id} environment={organization.environment} canManage={['OWNER','ADMIN'].includes(organization.role)}/></>}
          {section === 'exports' && <ExportsScreen api={api} organization={organization} params={scopedParams} revision={revision} onRefresh={refresh} onGo={onGo}/>}
          {section === 'setup' && <SetupScreen api={api} organization={organization} session={session} params={scopedParams} canImport={!!context.data.capabilities.import} onGo={onGo}/>}
          {section === 'settings' && <><header className="records-page-heading"><div><span className="records-eyebrow">WORKSPACE CONTROLS</span><h1>Settings</h1><p>Current access, locations, and account preferences.</p></div></header><section className="records-panel"><h2>{organization.name}</h2><dl className="records-facts"><div><dt>Your role</dt><dd>{displayState(organization.role)}</dd></div><div><dt>Environment</dt><dd>{organization.environment === 'live' ? 'Production' : 'Sandbox'}</dd></div><div><dt>Locations</dt><dd>{organization.locations.map(location => location.name).join(', ') || 'No location restriction configured'}</dd></div><div><dt>Activation</dt><dd>{organization.enabled ? 'Enabled for the released workspace cohort' : 'Waiting for activation'}</dd></div></dl><div className="records-actions"><LocalLink className="records-button secondary" href="/account" onGo={onGo}>Manage account preferences</LocalLink></div><p className="records-muted">Role changes and delegation are enforced by the server. Saved views do not grant access.</p></section>{context.data.capabilities.manage && <TeamSettings key={`${organization.id}.${organization.environment}`} api={api} organizationId={organization.id} currentUserId={session.userId} onChanged={refresh}/>}</>}
        </>}
        <footer className="records-footer"><span>PackProof · Neutral evidence infrastructure</span><span>Preserved originals. Clear provenance.</span></footer>
      </main>
    </div>
    {tour !== null && <div className="records-tour-backdrop"><TourDialog step={tour} onClose={leaveTour} onStep={setTour} onNavigate={target => { onGo(goSection(target)); }}/></div>}
  </div>;
}
function TourDialog({ step, onClose, onStep, onNavigate }: { step: number; onClose: () => void; onStep: (step: number) => void; onNavigate: (section: RecordsSection) => void }) {
  const dialog = useRef<HTMLDivElement>(null), previousFocus = useRef(document.activeElement as HTMLElement | null);
  useEffect(() => { dialog.current?.focus(); return () => previousFocus.current?.focus(); }, []);
  const info = TOUR[step];
  return <div ref={dialog} className="records-tour" role="dialog" aria-modal="true" aria-labelledby="records-tour-title" tabIndex={-1} onKeyDown={event => { if (event.key === 'Escape') onClose(); if (event.key === 'Tab') { const buttons = dialog.current?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)'); if (!buttons?.length) return; if (event.shiftKey && (document.activeElement === buttons[0] || document.activeElement === dialog.current)) { event.preventDefault(); buttons[buttons.length - 1].focus(); } else if (!event.shiftKey && document.activeElement === buttons[buttons.length - 1]) { event.preventDefault(); buttons[0].focus(); } } }}><button className="records-icon-button records-tour-close" aria-label="Close guided tour" onClick={onClose}><Glyph name="close"/></button><span className="records-eyebrow">QUICK TOUR · {step + 1} OF {TOUR.length}</span><h2 id="records-tour-title">{info.title}</h2><p>{info.body}</p><button className="records-text-button" onClick={() => onNavigate(step === 1 ? 'attention' : step === 3 ? 'connections' : step === 4 ? 'exports' : 'records')}>Open this part of the workspace<Glyph size={16}/></button><div className="records-tour-progress" aria-hidden="true">{TOUR.map((_, index) => <i key={index} className={index === step ? 'active' : ''}/>)}</div><div className="records-actions"><button className="records-button secondary" disabled={step === 0} onClick={() => onStep(step - 1)}>Back</button><button className="records-button" onClick={() => step === TOUR.length - 1 ? onClose() : onStep(step + 1)}>{step === TOUR.length - 1 ? 'Start using records' : 'Next'}</button></div></div>;
}
